source.@value:
rule "Normalize VEEAM backup result fields"
when
  has_field("message_type") AND to_string($message.message_type) == "VEEAM_JOB_RESULT"
then
  set_field("job_start_time", $message.start_time);
  set_field("job_end_time", $message.end_time);
  set_field("job_duration_seconds", $message.duration_seconds);
  set_field("job_duration_minutes", $message.duration_minutes);
  set_field("vm_count", $message.objects_total);
  set_field("vms_success", $message.objects_success);
  set_field("vms_warning", $message.objects_warning);
  set_field("vms_failed", $message.objects_failed);
  set_field("backup_source", "veeam");
end

rule "Normalize PVE backup result fields"
when
  has_field("message_type") AND to_string($message.message_type) == "PVE_BACKUP_RESULT"
then
  set_field("start_time", $message.job_start_time);
  set_field("end_time", $message.job_end_time);
  set_field("duration_seconds", $message.job_duration_seconds);
  set_field("duration_minutes", $message.job_duration_minutes);
  set_field("objects_total", $message.vm_count);
  set_field("objects_success", $message.vms_success);
  set_field("objects_warning", $message.vms_warning);
  set_field("objects_failed", $message.vms_failed);
  set_field("backup_source", "proxmox");
end
